function escapeRegExp(value) {
return value.replace(/[.*+?^\${}()|[\\]\\\\]/g, '\\\\$&');
}
function mark(text, needle, highlight, occurrence = 1) {
const matches = [...text.matchAll(new RegExp(escapeRegExp(needle), 'g'))];
if (matches.length < occurrence) throw new Error('Highlight target missing');
const start = matches[occurrence - 1].index; // JavaScript UTF-16 position
return { start, end: start + needle.length, highlight };
}
function validateRuns(text, runs) {
for (const run of runs) {
if (!Number.isInteger(run.start) || !Number.isInteger(run.end) ||
run.start < 0 || run.end > text.length || run.start >= run.end) {
throw new Error('Invalid formatting interval');
}
}
// Apply the current site's overlap and normalization rules.
}
